const PO_LABEL={draft:"Draft",sent:"Ordered",partial:"Partially received",received:"Received",cancelled:"Cancelled"};
function poTag(o){ const cls={draft:"",sent:"info",partial:"warn",received:"ok",cancelled:"bad"}[o.status]||""; const overdue=["sent","partial"].includes(o.status)&&o.expected&&o.expected<todayISO(); return `<span class="tag ${overdue?"bad":cls}">${PO_LABEL[o.status]||esc(o.status)}${overdue?" · overdue":""}</span>`; }
