function poSearch(id,q){ q=q.toLowerCase(); const o=byId("purchaseOrders",id); const r=document.getElementById("po_res"); if(!q){r.innerHTML="";return} const hits=S.products.filter(p=>(p.vendorId===o.vendorId||!o.vendorId)&&[p.sku,p.name,p.vendorSku].join(" ").toLowerCase().includes(q)).slice(0,8); r.innerHTML=hits.length?`<div class="search-res">${hits.map(p=>`<div onclick="poAdd('${id}','${p.id}')"><span><b>${esc(p.sku)}</b> ${esc(p.name)} <span class="muted">stock ${p.stock||0}</span></span><span>${money(p.cost)}</span></div>`).join("")}</div>`:""; }
